#Region Seed WFP Assumptions — planning drivers, per Period x Version x Entity
# Phase 3.5: each CALCULATED version carries its OWN complete assumption set.
#   Budget   = the approved/frozen plan: no merit, no promo, no bonus, no actuals
#              blend (Actuals Cutoff Index 0). Preserves the Phase 1/2 Budget
#              assertion suite.
#   Forecast = the working current model: 3% merit + 1% promo from review index
#              16, 10% bonus pool, actuals blend to index 15.
#   Downside = a self-contained cost-pressure scenario: 5% merit, 4% inflation,
#              12% bonus, faster fill (5% vacancy), actuals blend to index 15.
# Idempotent. Written at leaf entities only (Group is a consolidation). Rules read
# at the position's Home Entity. Edit per cell after where a driver varies by year. 
# Line added here to test Deploy further test added this
cCube = 'WFP Assumptions';
cPer  = 'WFP Period';
nPcount = DIMSIZ( cPer );

# measure ; Budget ; Forecast ; Downside
vM =
'Merit Increase %;0;0.03;0.05~' |
'Promotion Budget %;0;0.01;0.01~' |
'Inflation %;0.025;0.025;0.04~' |
'Actuals Cutoff Index;0;15;15~' |
'Merit Review Index;0;16;16~' |
'Vacancy Allowance %;0.10;0.10;0.05~' |
'Standard FTE Hours;160;160;160~' |
'Bonus Pool %;0;0.10;0.12~' |
'Employer Oncost Fallback %;0.15;0.15;0.15~';

vEnts = 'UK Ltd|US Inc|NZ Ltd|';

nP = 1;
WHILE( nP <= nPcount );
   vPer = DIMNM( cPer, nP );
   IF( DTYPE( cPer, vPer ) @= 'N' & ( LONG( vPer ) = 7 % ATTRS( cPer, vPer, 'Period Type' ) @= 'Opening' ) );
      vEl = vEnts;
      WHILE( SCAN( '|', vEl ) > 1 );
         nS = SCAN( '|', vEl ); vEnt = SUBST( vEl, 1, nS - 1 ); vEl = SUBST( vEl, nS + 1, LONG( vEl ) - nS );
         vRows = vM;
         WHILE( SCAN( '~', vRows ) > 1 );
            nS = SCAN( '~', vRows ); vRec = SUBST( vRows, 1, nS - 1 ) | ';'; vRows = SUBST( vRows, nS + 1, LONG( vRows ) - nS );
            nS = SCAN( ';', vRec ); vMeas = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
            nS = SCAN( ';', vRec ); nBud  = NUMBR( SUBST( vRec, 1, nS - 1 ) ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
            nS = SCAN( ';', vRec ); nFcst = NUMBR( SUBST( vRec, 1, nS - 1 ) ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
            nS = SCAN( ';', vRec ); nDwn  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
            CellPutN( nBud,  cCube, vPer, 'Budget',   vEnt, vMeas );
            CellPutN( nFcst, cCube, vPer, 'Forecast', vEnt, vMeas );
            CellPutN( nDwn,  cCube, vPer, 'Downside', vEnt, vMeas );
         END;
      END;
   ENDIF;
   nP = nP + 1;
END;
